package com.kareem.cortex;

import android.database.Cursor;
import java.util.*;

/** Read model for Now/Brief. Raw capture never becomes a Brief item by itself. */
public final class PrimeBriefStore {
    private PrimeBriefStore(){}
    public static final class Item {public final long id,threadId,signalId,updatedAt;public final String kind,title,body,source,state;public final double confidence;public final int importance;Item(long id,String kind,String title,String body,String source,String state,double confidence,int importance,long threadId,long signalId,long updatedAt){this.id=id;this.kind=n(kind);this.title=n(title);this.body=n(body);this.source=n(source);this.state=n(state);this.confidence=confidence;this.importance=importance;this.threadId=threadId;this.signalId=signalId;this.updatedAt=updatedAt;}}
    public static final class Snapshot {public final ArrayList<KnowledgeItem> recent;public final ArrayList<Item> actions,waiting,decisions,changes,worthKnowing;public final ArrayList<ReviewQueueStore.Item> reviews;Snapshot(ArrayList<KnowledgeItem> recent,ArrayList<Item>a,ArrayList<Item>w,ArrayList<Item>d,ArrayList<Item>c,ArrayList<Item>k,ArrayList<ReviewQueueStore.Item>r){this.recent=recent;actions=a;waiting=w;decisions=d;changes=c;worthKnowing=k;reviews=r;}public boolean empty(){return recent.isEmpty()&&actions.isEmpty()&&waiting.isEmpty()&&decisions.isEmpty()&&reviews.isEmpty()&&changes.isEmpty()&&worthKnowing.isEmpty();}}
    public static Snapshot load(VaultDb db){CognitiveStore.ensure(db);UniversalEventStore.ensure(db.getWritableDatabase());return new Snapshot(intentionalCaptures(db,6),attention(db,"ACTION",12),attention(db,"WAITING",12),attention(db,"DECISION",8),meaningfulChanges(db,12),legacyWorthKnowing(db,8),ReviewQueueStore.pending(db,12));}
    private static ArrayList<KnowledgeItem> intentionalCaptures(VaultDb db,int limit){ArrayList<KnowledgeItem> out=new ArrayList<>();for(KnowledgeItem k:db.captureSearch("",120)){String s=n(k.source);if(!("manual".equals(s)||"quick_capture".equals(s)||"android_share".equals(s)))continue;out.add(k);if(out.size()>=limit)break;}return out;}
    private static ArrayList<Item> attention(VaultDb db,String kind,int limit){
        ArrayList<Item> out=new ArrayList<>();
        Cursor c=db.getReadableDatabase().rawQuery("SELECT a.id,a.kind,a.title,a.body,a.source_key,a.state,a.confidence,a.priority,a.situation_id,a.semantic_event_id,a.updated_at FROM ue_attention_items a WHERE a.kind=? AND a.state='open' ORDER BY a.priority DESC,a.updated_at DESC LIMIT ?",new String[]{kind,String.valueOf(limit*2)});while(c.moveToNext())out.add(new Item(UniversalEventStore.ATTENTION_COMPAT_OFFSET+c.getLong(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getString(5),c.getDouble(6),c.getInt(7),c.getLong(8),0,c.getLong(10)));c.close();
        if(out.size()<limit){
            // During the non-destructive v64/v65 transition, a previously derived notification
            // action must not disappear merely because its raw evidence predates the universal
            // ledger. Only high-confidence legacy ACTION/WAITING/DECISION items are admitted as
            // a compatibility projection; the notification itself is still NOT memory.
            Cursor l=db.getReadableDatabase().rawQuery("SELECT d.id,d.kind,d.title,d.body,d.source_key,d.state,d.confidence,d.importance,d.thread_id,d.anchor_signal_id,d.updated_at FROM derived_items d WHERE d.kind=? AND d.state='open' AND COALESCE(d.candidate_kind,'')<>'UE_ATTENTION' AND (NOT EXISTS(SELECT 1 FROM raw_signals r WHERE r.id=d.anchor_signal_id AND r.kind='notification') OR d.confidence>=0.85) ORDER BY d.importance DESC,d.updated_at DESC LIMIT ?",new String[]{kind,String.valueOf(limit)});while(l.moveToNext())out.add(fromLegacy(l));l.close();
        }
        return dedupe(out,limit);
    }
    private static ArrayList<Item> meaningfulChanges(VaultDb db,int limit){ArrayList<Item> out=new ArrayList<>();long since=System.currentTimeMillis()-48L*60L*60L*1000L;Cursor c=db.getReadableDatabase().rawQuery("SELECT e.id,e.semantic_type,e.subject,e.summary,s.source_type,e.semantic_state,e.confidence,CASE WHEN e.semantic_type IN ('decision','commitment','action_request') THEN 75 ELSE 45 END,e.stream_id,e.raw_observation_id,e.occurred_at FROM ue_semantic_events e JOIN ue_streams s ON s.id=e.stream_id WHERE e.meaningful=1 AND e.superseded_by=0 AND e.semantic_type<>'technical_state' AND e.occurred_at>=? ORDER BY e.occurred_at DESC LIMIT ?",new String[]{String.valueOf(since),String.valueOf(limit*3)});while(c.moveToNext())out.add(new Item(c.getLong(0),"CHANGE",CanonicalPresentation.cleanTitle(c.getString(4),c.getString(1),c.getString(2),c.getString(2)),c.getString(3),c.getString(4),c.getString(5),c.getDouble(6),c.getInt(7),c.getLong(8),0,c.getLong(10)));c.close();return dedupe(out,limit);}
    private static ArrayList<Item> legacyWorthKnowing(VaultDb db,int limit){ArrayList<Item> out=new ArrayList<>();Cursor c=db.getReadableDatabase().rawQuery("SELECT id,kind,title,body,source_key,state,confidence,importance,thread_id,anchor_signal_id,updated_at FROM derived_items WHERE state='open' AND COALESCE(candidate_kind,'')<>'UE_ATTENTION' AND kind IN ('IDEA','OPPORTUNITY','INSIGHT','HYPOTHESIS') AND NOT EXISTS(SELECT 1 FROM raw_signals r WHERE r.id=anchor_signal_id AND r.kind='notification') ORDER BY importance DESC,updated_at DESC LIMIT ?",new String[]{String.valueOf(limit*3)});while(c.moveToNext())out.add(fromLegacy(c));c.close();return dedupe(out,limit);}
    private static Item fromLegacy(Cursor c){return new Item(c.getLong(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getString(5),c.getDouble(6),c.getInt(7),c.getLong(8),c.getLong(9),c.getLong(10));}
    private static ArrayList<Item> dedupe(ArrayList<Item> xs,int limit){LinkedHashMap<String,Item> map=new LinkedHashMap<>();for(Item x:xs){String basis=!x.body.isEmpty()?x.body:x.title;String key=x.kind+"|"+LocalSemanticEmbedder.norm(basis);if(key.length()>200)key=key.substring(0,200);Item old=map.get(key);if(old==null||x.importance>old.importance||x.updatedAt>old.updatedAt)map.put(key,x);}ArrayList<Item> out=new ArrayList<>(map.values());out.sort((a,b)->{int z=Integer.compare(b.importance,a.importance);return z!=0?z:Long.compare(b.updatedAt,a.updatedAt);});if(out.size()>limit)return new ArrayList<>(out.subList(0,limit));return out;}
    private static String n(String s){return s==null?"":s.trim();}
}
